// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CoinToken {
    function owner() external view returns (address);
    function enableBlacklist(address account) external;
    function isBlacklisted(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF9881a0Bf01b1ec048506A188B06d48808087657;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner during the exploit
        // The test framework already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the current owner of the contract
        address owner = CoinToken(TARGET).owner();

        // Step 2: Impersonate the owner and blacklist the attacker
        vm.prank(owner);
        CoinToken(TARGET).enableBlacklist(attacker);

        // Step 3: Verify the attacker is now blacklisted
        bool isBlacklisted = CoinToken(TARGET).isBlacklisted(attacker);
        require(isBlacklisted, "Attacker should be blacklisted");
        assertEq(isBlacklisted, true, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
